INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 10, 'theory', 'Quiz: registers and the clock');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 10, 0, 'What is a clock edge?', '["Any level of one", "The duration of one period", "A transition from 0 to 1 (or from 1 to 0, depending on the flip-flop)", "A transmission error"]', 2, 'Flip-flops trigger on the edge: at that moment they take the value from the input and hold it until the next edge.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 10, 1, 'The clock frequency is 2 GHz. What is the period?', '["2 ns", "0.5 ns", "0.2 ns", "5 ns"]', 1, 'T = 1 / f = 1 / (2·10⁹ Hz) = 0.5·10⁻⁹ s = 0.5 ns.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 10, 2, 'Why is a D flip-flop built from two latches?', '["One latch is too slow", "To double the memory capacity", "It is a standard requirement", "So the value reaches the output only at the moment of the edge, and not the whole time the clock is high"]', 3, 'The master accepts the input while the clock is zero, the slave outputs the value while the clock is one. While the clock is one, the master is closed and the input has no effect.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 10, 3, 'What happens if the inverted output Q̄ of a D flip-flop is fed to its own D input?', '["The flip-flop hangs", "The output toggles on every edge: a divide-by-two", "The flip-flop starts to remember a one", "A short circuit"]', 1, 'D = not Q: on every edge Q changes to the opposite value. The frequency of Q is half the clock frequency.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 10, 4, 'What limits the maximum clock frequency of a synchronous circuit?', '["The longest path between two registers: the period must be at least the sum of the delays", "The number of flip-flops", "The supply voltage", "The length of the clock wire"]', 0, 'T ≥ tcq + tlogic + tsetup. To raise the frequency, long paths are shortened or broken up with registers, and that is the pipeline.');
